TYPE ST_Pump :
STRUCT
    priority : INT;
    selection : BOOL;
    RunComd : BOOL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_P07
VAR_INPUT
    mode : BOOL;
    start : BOOL;
    stop : BOOL;
END_VAR
VAR_IN_OUT
    pumpGroup : ARRAY[1..5] OF ST_Pump;
END_VAR
VAR
    firstScan : BOOL := TRUE;
    startTrig : R_TRIG;
    runLatch : ARRAY[1..5] OF BOOL;
    selected : ARRAY[1..5] OF BOOL;
    i : INT;
    k : INT;
    currentCount : INT;
    bestIndex : INT;
    bestPriority : INT;
    manualFound : BOOL;
END_VAR

(*
  语义冲突报告（保留，不自行新增接口）：
  1) C6 要求 RunComd 保持到 stop 出现为止；题目又要求手动按 selection 单泵启停、
     自动按优先级三用两备。若 selection/priority/mode 改变时允许自行停止或切换，
     会与 C6 冲突。本实现按 C1/C2/C4/C6/C10 的安全保持语义执行：
     stop 是唯一清除所有 RunComd 的请求，运行后不因 selection、priority、mode 改变而自行掉线。
  2) 手动模式下若多个 pumpGroup[i].selection 同时为 TRUE，题目未定义唯一选择规则。
     本实现为确定性只启动泵号最小的被选中泵，且不无 stop 停止其他已保持运行泵。
  3) 自动模式启动时在未运行泵中按优先级高者先启、同优先级泵号升序补足到 3 台。
     若历史保持或外部初态使已运行泵超过 3 台，则在不出现 stop 时不能自行停泵，
     因此无法同时满足 C6 与 K2“恰为 3 台”；该冲突按 C6 优先保留。
*)

IF firstScan THEN
    (* C10: 上电首周期无运行命令 *)
    FOR i := 1 TO 5 DO
        runLatch[i] := FALSE;
        pumpGroup[i].RunComd := FALSE;
    END_FOR;
    firstScan := FALSE;
ELSE
    IF stop THEN
        (* C1/C2/C4: stop 优先，当周期清除所有运行命令；start 同时有效也不启动 *)
        FOR i := 1 TO 5 DO
            runLatch[i] := FALSE;
            pumpGroup[i].RunComd := FALSE;
        END_FOR;
        startTrig(CLK := start);
    ELSE
        startTrig(CLK := start);

        IF startTrig.Q THEN
            IF mode THEN
                (* 自动模式：从当前未运行泵中补足到 3 台；已运行泵按 C6 保持 *)
                currentCount := 0;
                FOR i := 1 TO 5 DO
                    selected[i] := runLatch[i];
                    IF runLatch[i] THEN
                        currentCount := currentCount + 1;
                    END_IF;
                END_FOR;

                FOR k := 1 TO 3 DO
                    IF currentCount < 3 THEN
                        bestIndex := 0;
                        bestPriority := 0;
                        FOR i := 1 TO 5 DO
                            IF NOT selected[i] THEN
                                IF bestIndex = 0 THEN
                                    bestIndex := i;
                                    bestPriority := pumpGroup[i].priority;
                                ELSE
                                    IF (pumpGroup[i].priority > bestPriority) OR
                                       ((pumpGroup[i].priority = bestPriority) AND (i < bestIndex)) THEN
                                        bestIndex := i;
                                        bestPriority := pumpGroup[i].priority;
                                    END_IF;
                                END_IF;
                            END_IF;
                        END_FOR;

                        IF bestIndex > 0 THEN
                            runLatch[bestIndex] := TRUE;
                            selected[bestIndex] := TRUE;
                            currentCount := currentCount + 1;
                        END_IF;
                    END_IF;
                END_FOR;
            ELSE
                (* 手动模式：启动泵号最小的被选中泵；不做无 stop 的自行停止 *)
                manualFound := FALSE;
                FOR i := 1 TO 5 DO
                    IF (NOT manualFound) AND pumpGroup[i].selection THEN
                        runLatch[i] := TRUE;
                        manualFound := TRUE;
                    END_IF;
                END_FOR;
            END_IF;
        END_IF;

        (* 无 stop 时输出保持状态；每周期重写 RunComd，保证 C6 不自行掉线 *)
        FOR i := 1 TO 5 DO
            pumpGroup[i].RunComd := runLatch[i];
        END_FOR;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
